+.glass-card {
+  border: 1px solid;
+  transition: all 0.5s cubic-bezier(0.25, 0.8, 0.25, 1); /* Smoother transition for liquid feel */
+  background: hsl(var(--card) / 0.6);
+  backdrop-filter: blur(25px); /* Increased blur for a more glassy effect */
+  -webkit-backdrop-filter: blur(25px);
+  border-color: hsl(var(--border) / 0.8);
+  @apply dark:bg-card/40 dark:border-border/10;
+}
